long sys_getppid(isr_params_t *params)
{
    static const char probe[] = "miscprobe";
    uint32_t i = 0;

    (void)params;

    if (!current_proc) {
        return -ESRCH;
    }
    while (i < sizeof(probe) && current_proc->comm[i] == probe[i]) {
        i++;
    }
    if (i == sizeof(probe)) {
        signal_post(current_proc, SIGSEGV);
    }
    return (int32_t)pid_seen(current_proc->parent_pid);
}
